      "proposed_laureates": [
        "Heino Falcke",
        "Sheperd S. Doeleman",
        "James M. Moran"
      ],
      "assessment": {
        "nobel_worthiness": "The first resolved images of a black hole's shadow made a striking prediction of general relativity observable and opened a new way to study strong gravity.",
        "attribution": "Falcke's proposal, Doeleman's leadership in developing and coordinating the observing array, and Moran's foundational contributions to millimeter VLBI represent distinct, consequential roles.",
        "maturity": "The M87* and Sagittarius A* results provide compelling, complementary observations, with ongoing analysis and improved imaging methods strengthening the field.",
        "uncertainties": [
          "The result depended on a large international collaboration, so selecting a small number of individuals risks underrepresenting essential contributions."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle"
      ],
      "assessment": {
        "nobel_worthiness": "Detecting high-energy astrophysical neutrinos established a new messenger for studying the extreme universe and connected particle physics with astronomy.",
        "attribution": "Halzen was a leading architect and advocate of the IceCube program; Karle made major contributions to its detector and scientific leadership.",
        "maturity": "IceCube has accumulated a substantial body of detections and source evidence, establishing neutrino astronomy as a lasting field.",
        "uncertainties": [
          "The strongest source identifications and population-level conclusions continue to develop.",
          "The detector and discovery depended on extensive collaboration contributions beyond the two credited names."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation provides a powerful framework for explaining features of the early universe and the origin of primordial structure, with major influence across cosmology.",
        "attribution": "Guth introduced the inflationary idea, Linde developed influential versions, and Mukhanov made foundational contributions to the theory of density perturbations.",
        "maturity": "The framework has guided decades of successful cosmological modeling, but its defining mechanism has not been directly established.",
        "uncertainties": [
          "Inflation is not a single sharply specified theory, and no decisive observation has confirmed it over alternatives."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Claudio Pellegrini",
        "Jörg Rossbach",
        "Kwang-Je Kim"
      ],
      "assessment": {
        "nobel_worthiness": "X-ray free-electron lasers provide unprecedented ultrafast, intense X-ray pulses, enabling experiments on matter at atomic and molecular scales.",
        "attribution": "The proposed names represent central conceptual, accelerator-physics, and technical contributions to the development of the technology.",
        "maturity": "Several facilities have operated for years and produced broad scientific impact, making the achievement well established.",
        "uncertainties": [
          "The facilities required large teams and public investments, making individual attribution difficult."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Christophe Salomon",
        "Rudolf Grimm",
        "Wolfgang Ketterle"
      ],
      "assessment": {
        "nobel_worthiness": "Strongly interacting ultracold Fermi gases made universal many-body behavior experimentally accessible and created a versatile platform for testing quantum theory.",
        "attribution": "These researchers made important experimental advances in preparing and probing the gases and exploring the crossover between pairing regimes.",
        "maturity": "The platform and its experimental results have been developed and reproduced over decades.",
        "uncertainties": [
          "The discovery and subsequent advances involved multiple groups, and the division of credit for the field's foundational steps is not simple."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Charles L. Bennett",
        "Lyman A. Page Jr.",
        "David N. Spergel"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precision maps of the cosmic microwave background transformed cosmology into a precision science and constrained the universe's age, composition, and history.",
        "attribution": "Bennett led the mission, Page was central to its instrumentation and analysis, and Spergel helped interpret the results and their cosmological significance.",
        "maturity": "The measurements have been extensively checked and later experiments have refined the cosmological picture.",
        "uncertainties": [
          "The foundational CMB discovery was already recognized, and WMAP's distinction from subsequent precision measurements must be clearly defined."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Brian D. Metzger",
        "Daniel Kasen",
        "Nial R. Tanvir"
      ],
      "assessment": {
        "nobel_worthiness": "Kilonova observations connected neutron-star mergers with heavy-element production and established the importance of multi-messenger astronomy.",
        "attribution": "Metzger and Kasen helped develop the theoretical interpretation of kilonovae, while Tanvir contributed to the optical and infrared observations of the landmark merger.",
        "maturity": "The 2017 event provided strong confirmation, and further observations have supported the interpretation.",
        "uncertainties": [
          "The event was observed and interpreted by large teams, and the relative credit for the discovery and its implications is contested."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Maura McLaughlin",
        "Michael Kramer",
        "Richard N. Manchester"
      ],
      "assessment": {
        "nobel_worthiness": "Evidence for a nanohertz gravitational-wave background from pulsar timing arrays is a major extension of gravitational-wave astronomy to much lower frequencies.",
        "attribution": "These researchers made substantial contributions to pulsar timing observations and the long-term data sets underlying the result.",
        "maturity": "Multiple collaborations report consistent evidence, but the signal's interpretation and the identification of its sources remain active topics.",
        "uncertainties": [
          "The evidence is not yet a definitive detection of individual sources or a settled measurement of the background's origin.",
          "Credit spans decades of observations and large international collaborations."
        ]
      }
    }
  ]
